export class NdefUtil {
    /**
     * Convert a string to an array of UTF-8 bytes
     */
    private static stringToBytes(str: string): number[] {
        const encoder = new TextEncoder();
        const uint8Array = encoder.encode(str);
        return Array.from(uint8Array);
    }

    /**
     * Creates a standard NDEF Text Record exactly as phonegap-nfc expects it
     * This is 100% compatible with the ttdhV12 app
     */
    public static createTextRecord(
        text: string,
        languageCode: string = 'fr'
    ): { tnf: number; type: number[]; id: number[]; payload: number[] } {
        console.log(`📝 NdefUtil.createTextRecord: Creating record for text "${text}" with lang "${languageCode}"`);

        // Step 1: Convert language code and text to bytes
        const langBytes = this.stringToBytes(languageCode.toLowerCase());
        const textBytes = this.stringToBytes(text);

        // Step 2: Create the payload - status byte + lang + text
        const statusByte = langBytes.length; // Bit 7 = 0 (UTF-8), bits 0-5 = lang length
        const payload = [statusByte, ...langBytes, ...textBytes];

        console.log(`📊 Payload details:`, {
            statusByte,
            langLength: langBytes.length,
            langBytes: langBytes.map(b => String.fromCharCode(b)).join(''),
            textBytes: textBytes.map(b => String.fromCharCode(b)).join(''),
            totalPayloadLength: payload.length
        });
        console.log(`🔢 Full payload array:`, payload);

        const record = {
            tnf: 0x01, // TNF_WELL_KNOWN (0x01)
            type: [0x54], // RTD_TEXT (T)
            id: [], // Empty ID
            payload: payload
        };
        console.log(`✅ Final NDEF record:`, record);

        return record;
    }
}
